#include <cmath>
#include <map>

// ==============================
// 1. CONFIGURATION & NAMESPACES
// ==============================
namespace fs = boost::filesystem;
namespace po = boost::program_options;

// Configuration Structure: Holds all paths and settings.
// Used to decouple hard-coded values from the main logic flow.
struct Config {
    std::string dataDir; // Directory containing input CSV/JSON files
    std::string dbPath;  // Path to the SQLite database file
    std::string reportDir; // Directory where output reports will be saved
};

// ==============================
// 2. NLP ANALYZER CLASS
// ==============================
class NLPAnalyzer {
private:
    /**
     * Performs basic word segmentation (Tokenization).
     * Breaks text into individual words or tokens based on Chinese or English patterns.
     * This is a lightweight replacement for heavy NLP libraries like NLTK/Jieba.
     * 
     * @param text The input string to process.
     * @return A vector of strings containing the segmented words.
     */
    std::vector<std::string> segmentText(const std::string& text) {
        std::vector<std::string> words;

        // Regex Pattern: 
        // 1. [\\u4e00-\\u9fa5]+ : Matches 1 or more Chinese characters.
        // 2. | : Logical OR.
        // 3. [a-zA-Z0-9]+ : Matches 1 or more English letters or numbers.
        std::regex regexPattern("[\\u4e00-\\u9fa5]+|[a-zA-Z0-9]+");

        // iterator over matches in the text
        std::sregex_token_iterator iter(text.begin(), text.end(), regexPattern);
        std::sregex_token_iterator end;

        while (iter != end) {
            words.push_back(*iter++); // Add each word to the result vector
        }
        return words;
    }

public:
    /**
     * Analyzes sentiment using a simple scoring heuristic.
     * This mimics the 'VADER' sentiment analyzer. It scores text based on keyword presence.
     * 
     * @param text The text string to analyze.
     * @return A sentiment score between 0.0 (Negative) and 1.0 (Positive).
     */
    double analyzeSentiment(const std::string& text) {
        double score = 0.0;

        // Step 1: Tokenize the text into words
        std::vector<std::string> words = segmentText(text);

        // Step 2: Simple keyword scoring (Mock dictionary)
        for (const auto& w : words) {
            if (w == "good" || w == "satisfied" || w == "happy") score += 0.2;  // Positive boost
            if (w == "bad" || w == "slow" || w == "error") score -= 0.2;        // Negative penalty
        }

        // Step 3: Clamp score between 0 and 1
        return std::max(0.0, std::min(1.0, 0.5 + score));
    }
};

// ==============================
// 3. DATA CLEANER CLASS
// ==============================
class DataCleaner {
private:
    std::string timeFormatStr = "%Y-%m-%d %H:%M:%S"; // Format standardization target

public:
    /**
     * Cleans a single text string.
     * Removes special characters, standardizes whitespace, and removes noise.
     * 
     * @param text The raw text to clean.
     * @return The cleaned string.
     */
    std::string cleanText(const std::string& text) {
        if (text.empty()) return "";

        // Regex: Matches anything that is NOT (Chinese chars OR English OR Numbers OR Space)
        // Basically: Remove emojis, symbols, and punctuation.
        std::regex pattern("[^\\u4e00-\\u9fa5a-zA-Z0-9\\s]");

        // Replace all matches with an empty string (removal)
        return std::regex_replace(text, pattern, "");
    }

    /**
     * Removes duplicate rows from a data set.
     * Uses a simple hash logic on the first column to identify duplicates.
     * 
     * @param rows The vector of data rows (maps).
     * @return A new vector containing only unique rows.
     */
    std::vector<std::map<std::string, std::string>> removeDuplicates(std::vector<std::map<std::string, std::string>>& rows) {
        std::vector<std::map<std::string, std::string>> uniqueRows;

        // Set for O(1) lookup speed. Stores the hash key of seen rows.
        std::set<std::string> seen;

        for (auto& row : rows) {
            std::string key;

            // Construct a simple unique key based on the first key-value pair
            if (!row.empty()) {
                key = row.begin()->first + row.begin()->second;
            }

            // If we haven't seen this key before, add it to uniqueRows and mark as seen
            if (seen.find(key) == seen.end()) {
                seen.insert(key);
                uniqueRows.push_back(row);
            }
        }
        return uniqueRows;
    }

    /**
     * Handles missing values (NULL or Empty).
     * Replaces empty strings with a placeholder string.
     * 
     * @param row The specific data row to clean.
     */
    void handleMissingValues(std::map<std::string, std::string>& row) {
        for (auto& kv : row) {
            if (kv.second.empty()) {
                kv.second = "Unknown"; // Replacement strategy for NULL values
            }
        }
    }
};

