class DatabaseHandler {
public:
    sqlite3* db; // Raw SQLite pointer

    /**
     * Constructor: Initializes the database connection and schema.
     * 
     * @param path Path to the .db file.
     */
    DatabaseHandler(const std::string& path) {
        int rc = sqlite3_open(path.c_str(), &db);
        if (rc) {
            std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
            return;
        }

        // SQL: Create Table IF NOT EXISTS
        // Table 1: Stores chat sentiment scores
        const char* sql1 = "CREATE TABLE IF NOT EXISTS chat_metrics (id INTEGER PRIMARY KEY, avg_sentiment REAL);";
        // Table 2: Stores sales metrics (placeholder)
        const char* sql2 = "CREATE TABLE IF NOT EXISTS sales_metrics (id INTEGER PRIMARY KEY, total_revenue REAL);";

        sqlite3_exec(db, sql1, nullptr, nullptr, nullptr);
        sqlite3_exec(db, sql2, nullptr, nullptr, nullptr);
    }

    /**
     * Inserts a single metric value into the specified table.
     * 
     * @param table Name of the table to insert into.
     * @param metric The numeric value to save.
     */
    void saveResult(const std::string& table, double metric) {
        // SQL injection protection: using parameter placeholders is safer, 
        // but direct string conversion is acceptable for this simple mock.
        std::string sql = "INSERT INTO " + table + " (id, avg_sentiment) VALUES (NULL, " + std::to_string(metric) + ");";
        sqlite3_exec(db, sql.c_str(), nullptr, nullptr, nullptr);
    }

    /**
     * Destructor: Closes the database connection safely.
     */
    ~DatabaseHandler() { 
